import type { ErrorDetail } from '../../../shared/domain/errors';
import { canonicalColumnName, canonicalColumnNames, type Dataset, type Row, type Scalar, toScalar } from '../../../shared/domain/tabular';

export interface ExpectedColumn {
  /** Canonical column name. */
  name: string;
  required: boolean;
}

export interface ImportedColumn {
  /** Header exactly as received; null for columns generated by ConsolidaHub (FILE_ID, VOLUME). */
  original: string | null;
  /** Canonical name used by rules and reports. */
  name: string;
}

export interface NormalizedImport {
  dataset: Dataset;
  /** Every dataset column, in order, with its provenance (dataset.columns === columns.map(name)). */
  columns: ImportedColumn[];
  issues: ErrorDetail[];
}

/** Columns added to every imported dataset for parity with the original `Sheets.LoadSheet`. */
export const FILE_ID_COLUMN = 'FILE_ID';
export const VOLUME_COLUMN = 'VOLUME';
const MAX_REPORTED_ISSUES = 50;

/**
 * Validates and canonicalizes the expected-column declaration of a source.
 * Returns the canonical list or the list of problems found.
 */
export function parseExpectedColumns(input: unknown): { columns: ExpectedColumn[]; issues: ErrorDetail[] } {
  const issues: ErrorDetail[] = [];
  if (!Array.isArray(input)) return { columns: [], issues: [{ field: 'expectedColumns', message: 'deve ser uma lista' }] };
  if (input.length > 500) issues.push({ field: 'expectedColumns', message: 'no máximo 500 colunas' });
  const columns: ExpectedColumn[] = [];
  const seen = new Set<string>();
  input.forEach((entry, index) => {
    const path = `expectedColumns[${index}]`;
    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
      issues.push({ field: path, message: 'deve ser um objeto { name, required }' });
      return;
    }
    const record = entry as Record<string, unknown>;
    const extra = Object.keys(record).filter((key) => key !== 'name' && key !== 'required');
    if (extra.length > 0) issues.push({ field: path, message: `propriedades não permitidas: ${extra.join(', ')}` });
    const name = typeof record.name === 'string' ? canonicalColumnName(record.name) : '';
    if (!name || name.length > 128) {
      issues.push({ field: `${path}.name`, message: 'nome de coluna inválido' });
      return;
    }
    if (seen.has(name)) {
      issues.push({ field: `${path}.name`, message: `coluna ${name} repetida` });
      return;
    }
    if (record.required !== undefined && typeof record.required !== 'boolean') {
      issues.push({ field: `${path}.required`, message: 'deve ser verdadeiro ou falso' });
      return;
    }
    seen.add(name);
    columns.push({ name, required: record.required !== false });
  });
  return { columns, issues };
}

/**
 * Builds the canonical dataset of an import from a header row and data rows:
 * canonical unique column names, one object per row with every column, empty strings → null,
 * FILE_ID overwritten with the file identifier and VOLUME = 1 added when absent.
 * Checks the declared expected columns and reports rows wider than the header.
 */
export function normalizeTabularImport(params: {
  header: readonly unknown[];
  rows: ReadonlyArray<readonly unknown[]>;
  fileId: string;
  expectedColumns: readonly ExpectedColumn[];
}): NormalizedImport {
  const issues: ErrorDetail[] = [];
  const canonical = canonicalColumnNames(params.header);
  const columns: ImportedColumn[] = canonical.map((name, index) => ({
    original: String(params.header[index] ?? ''),
    name,
  }));

  const missing = params.expectedColumns.filter((column) => column.required && !canonical.includes(column.name));
  for (const column of missing) {
    issues.push({ code: 'MISSING_COLUMN', field: column.name, message: `Coluna obrigatória ${column.name} não encontrada.` });
  }

  const rows: Row[] = [];
  params.rows.forEach((cells, index) => {
    if (cells.length > canonical.length && cells.slice(canonical.length).some((cell) => !isEmptyCell(cell))) {
      if (issues.length < MAX_REPORTED_ISSUES) {
        issues.push({
          code: 'EXTRA_FIELDS',
          field: `linha ${index + 2}`,
          message: `Linha com ${cells.length} campos para ${canonical.length} colunas no cabeçalho.`,
        });
      }
      return;
    }
    const row: Row = {};
    canonical.forEach((name, position) => {
      row[name] = cellValue(cells[position]);
    });
    rows.push(row);
  });

  if (!canonical.includes(FILE_ID_COLUMN)) columns.push({ original: null, name: FILE_ID_COLUMN });
  const addVolume = !canonical.includes(VOLUME_COLUMN);
  if (addVolume) columns.push({ original: null, name: VOLUME_COLUMN });
  for (const row of rows) {
    row[FILE_ID_COLUMN] = params.fileId;
    if (addVolume) row[VOLUME_COLUMN] = 1;
  }

  return { dataset: { columns: columns.map((column) => column.name), rows }, columns, issues };
}

function isEmptyCell(cell: unknown): boolean {
  return cell === null || cell === undefined || (typeof cell === 'string' && cell.trim() === '');
}

function cellValue(cell: unknown): Scalar {
  const scalar = toScalar(cell);
  return typeof scalar === 'string' && scalar.trim() === '' ? null : scalar;
}
